import bisect, hashlib

def h(s):
    return int(hashlib.md5(s.encode()).hexdigest()[:8], 16)

class Ring:
    def __init__(self, servers):
        # sorted token list + parallel owner list; lookup is O(log T)
        pairs = sorted((h(s), s) for s in servers)
        self.tokens = [t for t, _ in pairs]
        self.owners = [s for _, s in pairs]

    def lookup(self, key):
        i = bisect.bisect_left(self.tokens, h(key))  # smallest token >= hash
        if i == len(self.tokens):                    # past the largest: wrap
            i = 0
        return self.owners[i]

ring = Ring(["alpha", "beta", "gamma"])
for t, o in zip(ring.tokens, ring.owners):
    print("token %10d -> %s" % (t, o))
for k in ["user:1", "user:2", "user:3", "user:4"]:
    print(k, "hash", h(k), "->", ring.lookup(k))
# a key hashing exactly to a token belongs to that token (>=, not >)
exact = ring.tokens[1]
print("exact hit", exact, "->", ring.owners[bisect.bisect_left(ring.tokens, exact)])

import hashlib

def h(s):
    return int(hashlib.md5(s.encode()).hexdigest()[:8], 16)

def shares(servers, v, keys):
    # every server appears v times on the ring (virtual nodes)
    ring = sorted((h("%s#%d" % (s, i)), s) for s in servers for i in range(v))
    tokens = [t for t, _ in ring]
    count = {s: 0 for s in servers}
    import bisect
    for k in keys:
        i = bisect.bisect_left(tokens, h(k)) % len(ring)
        count[ring[i][1]] += 1
    return count

servers = ["s%d" % i for i in range(5)]
keys = ["k%d" % i for i in range(10000)]
print("10000 keys over 5 servers (ideal 2000 each)")
for v in (1, 10, 200):
    c = shares(servers, v, keys)
    vals = list(c.values())
    print("v=%3d counts=%s max/avg=%.2f" % (v, vals, max(vals) / 2000))

import hashlib

def score(server, key):
    return int(hashlib.md5((server + "|" + key).encode()).hexdigest()[:8], 16)

def owners(key, servers, k=1):
    # rendezvous (HRW): rank every server by hash(server, key), take top k
    return sorted(servers, key=lambda s: score(s, key), reverse=True)[:k]

servers = ["a", "b", "c", "d"]
keys = ["k%d" % i for i in range(1000)]
before = {k: owners(k, servers)[0] for k in keys}
after = {k: owners(k, servers + ["e"])[0] for k in keys}
moved = [k for k in keys if before[k] != after[k]]
print("keys moved after adding e:", len(moved), "of 1000")
print("all moved keys went to e:", all(after[k] == "e" for k in moved))
print("top-3 replicas for k7:", owners("k7", servers, 3), "(always distinct)")
